  `currencyref_value` varchar(10) DEFAULT NULL,
  `currencyref_name` varchar(50) DEFAULT NULL,
  `vendorref_value` bigint DEFAULT NULL,
  `vendorref_name` varchar(255) DEFAULT NULL,
  `apaccountref_value` bigint DEFAULT NULL,
