  `vendoraddr_city` varchar(100) DEFAULT NULL,
  `vendoraddr_country` varchar(100) DEFAULT NULL,
  `vendoraddr_countrysubdivisioncode` varchar(100) DEFAULT NULL,
  `vendoraddr_postalcode` varchar(20) DEFAULT NULL,
