  `txntype` varchar(50) DEFAULT NULL,
  `recurdataref_value` varchar(255) DEFAULT NULL,
  `recurdataref_value2` varchar(255) DEFAULT NULL,
  `line_classref_value` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
