  `billaddr_country` varchar(100) DEFAULT NULL,
  `primaryemailaddr_address` varchar(50) DEFAULT NULL,
  `middlename` varchar(50) DEFAULT NULL,
  `familyname` varchar(50) DEFAULT NULL,
  `billaddr_line1` varchar(255) DEFAULT NULL,
  `billaddr_city` varchar(100) DEFAULT NULL,
  `billaddr_countrysubdivisioncode` varchar(64) DEFAULT NULL,
  `billaddr_postalcode` varchar(20) DEFAULT NULL,
  `primaryphone_freeformnumber` varchar(50) DEFAULT NULL,
