  `costrate` decimal(15,2) DEFAULT NULL,
  `taxidentifier` varchar(50) DEFAULT NULL,
  `billaddr_line2` varchar(255) DEFAULT NULL,
  `webaddr_uri` varchar(500) DEFAULT NULL,
  `suffix` varchar(20) DEFAULT NULL,
  `record_taken` enum('Yes','No') DEFAULT NULL,
  PRIMARY KEY (`id`)
