/*!50001 VIEW `revenue_ledger` AS select `p`.`id` AS `payment_id`,`p`.`line_linkedtxn_txnid` AS `payment_line_linkedtxn_txnid`,`p`.`customerref_name` AS `customer`,`i`.`docnumber` AS `invoice_doc_number`,`p`.`totalamt` AS `payment_amount`,`i`.`totalamt` AS `invoice_amount`,(`p`.`totalamt` - `i`.`totalamt`) AS `pending_payments`,`i`.`txndate` AS `invoice_date`,`i`.`line_description` AS `invoice_description`,`ac`.`name` AS `invoice_classref_name`,`i`.`classref_value` AS `invoice_classref_value`,`i`.`line_itemrefname` AS `invoice_itemrefname`,`sh`.`evergreen_pct_ads` AS `split_evergreen_pct_ads`,`sh`.`evergreen_pct_programmatic` AS `split_evergreen_pct_programmatic`,`sh`.`effective_date` AS `effective_date`,(case when (lower(`i`.`line_itemrefname`) like '%programmatic%') then `sh`.`evergreen_pct_programmatic` else `sh`.`evergreen_pct_ads` end) AS `evergreen_percentage`,(case when (lower(`i`.`line_itemrefname`) like '%programmatic%') then (case when (`sh`.`evergreen_pct_programmatic` is not null) then (1.0 - `sh`.`evergreen_pct_programmatic`) else NULL end) else (case when (`sh`.`evergreen_pct_ads` is not null) then (1.0 - `sh`.`evergreen_pct_ads`) else NULL end) end) AS `partner_percentage`,round((case when ((lower(`i`.`line_itemrefname`) like '%programmatic%') and (`sh`.`evergreen_pct_programmatic` is not null)) then (`p`.`totalamt` * `sh`.`evergreen_pct_programmatic`) when (`sh`.`evergreen_pct_ads` is not null) then (`p`.`totalamt` * `sh`.`evergreen_pct_ads`) else NULL end),2) AS `evergreen_compensation`,round((case when ((lower(`i`.`line_itemrefname`) like '%programmatic%') and (`sh`.`evergreen_pct_programmatic` is not null)) then (`p`.`totalamt` * (1.0 - `sh`.`evergreen_pct_programmatic`)) when (`sh`.`evergreen_pct_ads` is not null) then (`p`.`totalamt` * (1.0 - `sh`.`evergreen_pct_ads`)) else NULL end),2) AS `partner_compensation` from (((`allpayments` `p` left join `allinvoices` `i` on((`p`.`line_linkedtxn_txnid` = `i`.`id`))) left join `split_history` `sh` on((`i`.`classref_value` = `sh`.`show_qbo_id`))) left join `allclass` `ac` on((`i`.`classref_value` = `ac`.`id`))) */;
